package ro.eva.iflyglasses.protocol

/**
 * Reasamblează cadre complete din pachetele de notificare BLE (≤240 octeți/pachet).
 * Alimentează cu `feed(bytes)` fiecare notificare primită pe `NOTIFY_CMD_UUID`;
 * întoarce lista de cadre complete decodate până acum.
 *
 * Caută flag-ul de start AA FF 55 00, citește lungimea (offset 12, u16 LE) și
 * emite cadrul când s-au strâns HEADER_LEN + bodyLen octeți. Resincronizează
 * dacă apar octeți de gunoi înaintea unui flag valid.
 */
class FrameReassembler {
    private val buf = ArrayList<Byte>(512)

    fun feed(chunk: ByteArray): List<Frame> {
        for (b in chunk) buf.add(b)
        val out = ArrayList<Frame>()
        while (true) {
            val f = tryExtract() ?: break
            out.add(f)
        }
        return out
    }

    fun reset() = buf.clear()

    private fun tryExtract(): Frame? {
        // resincronizare: elimină octeții până la un posibil flag de start
        val start = indexOfStart()
        if (start < 0) {
            if (buf.size > 4) { val keep = buf.takeLast(3); buf.clear(); buf.addAll(keep) }
            return null
        }
        if (start > 0) repeat(start) { buf.removeAt(0) }
        if (buf.size < Protocol.HEADER_LEN + Protocol.CHECKSUM_LEN) return null
        val bodyLen = (buf[Protocol.Offset.LENGTH].toInt() and 0xFF) or
                ((buf[Protocol.Offset.LENGTH + 1].toInt() and 0xFF) shl 8)
        val total = Protocol.HEADER_LEN + bodyLen
        if (bodyLen <= 0 || total > 64 * 1024) { buf.removeAt(0); return null } // lungime absurdă -> resinc
        if (buf.size < total) return null
        val frameBytes = ByteArray(total) { buf[it] }
        repeat(total) { buf.removeAt(0) }
        return Frame.decode(frameBytes)
    }

    private fun indexOfStart(): Int {
        val f = Protocol.START_FLAG
        outer@ for (i in 0..buf.size - f.size) {
            for (j in f.indices) if (buf[i + j] != f[j]) continue@outer
            return i
        }
        return -1
    }
}

