package ro.eva.iflyglasses.protocol

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

class FrameTest {

    @Test fun headerFieldsAndLength() {
        val f = Frame.ofJson(linkedMapOf("opt" to Opt.RECORD_CONTROL, "optNum" to 1, "biz_num" to 0, "ctrl" to Opt.Rec.START))
        val bytes = f.encode()
        // flag start
        assertEquals("aaff5500", bytes.copyOfRange(0, 4).toHex())
        // versiune + opcode request
        assertEquals(Protocol.VERSION, bytes[Protocol.Offset.VERSION].toInt() and 0xFF)
        assertEquals(Protocol.Op.REQUEST, bytes[Protocol.Offset.OPCODE].toInt() and 0xFF)
        // lungime = payload + checksum
        val len = (bytes[12].toInt() and 0xFF) or ((bytes[13].toInt() and 0xFF) shl 8)
        assertEquals(f.payload.size + Protocol.CHECKSUM_LEN, len)
        assertEquals(Protocol.HEADER_LEN + f.payload.size + Protocol.CHECKSUM_LEN, bytes.size)
    }

    @Test fun roundTrip() {
        val original = Frame.ofJson(linkedMapOf("opt" to Opt.GET_SYSTEM_INFO, "optNum" to 7, "biz_num" to 0), seq = 42)
        val bytes = original.encode()
        val decoded = Frame.decode(bytes, verifyChecksum = true)
        assertNotNull(decoded)
        assertEquals(Protocol.Op.REQUEST, decoded.opcode) // opcode header e REQUEST; opt e în payload
        assertEquals(original.payloadText, decoded.payloadText)
        assertEquals(42, decoded.seq)
        assertTrue(decoded.payloadText.contains("\"opt\":62001"))
    }

    @Test fun reassemblerSplitsAndJoins() {
        val a = Commands().getSystemInfo().encode()
        val b = Commands().startRecord().encode()
        val stream = a + b
        val r = FrameReassembler()
        val collected = ArrayList<Frame>()
        // hrănește în bucăți de 7 octeți ca să simulăm fragmentarea MTU
        var i = 0
        while (i < stream.size) {
            val end = minOf(i + 7, stream.size)
            collected += r.feed(stream.copyOfRange(i, end))
            i = end
        }
        assertEquals(2, collected.size)
        assertTrue(collected[0].payloadText.contains("62001"))
        assertTrue(collected[1].payloadText.contains("62003"))
    }

    @Test fun commandPayloadShape() {
        val f = Commands(bizNum = 0).downloadFile("REC/0001.wav", offset = 0)
        val t = f.payloadText
        assertTrue(t.contains("\"opt\":70402"))
        assertTrue(t.contains("\"fileName\":\"REC/0001.wav\""))
        assertTrue(t.contains("\"upOrDown\":2"))
    }

    private fun ByteArray.toHex() = joinToString("") { "%02x".format(it.toInt() and 0xFF) }
}

