package ro.eva.iflyglasses.protocol

/**
 * Codec pentru cadrul binar BLE iFLYTEK Glasses.
 *
 * Structură (TENTATIV — se confirmă pe hardware la E2):
 *   [0..3]  AA FF 55 00            flag start
 *   [4..7]  seq (u32 LE)           id/secvență mesaj
 *   [8]     version = 1
 *   [9]     opcode  (1 req / 2 resp / 3 ind / 4 notify)
 *   [10..11] flags (u16 LE, 0)
 *   [12..13] length (u16 LE) = len(payload) + 1 (checksum)
 *   [14..]  payload JSON (UTF-8)
 *   [last]  checksum (1 octet)  <-- algoritm PLUGGABLE, de confirmat
 */
class Frame(
    val opcode: Int,
    val payload: ByteArray,
    val seq: Int = 0,
    val version: Int = Protocol.VERSION,
    val flags: Int = 0,
) {
    val payloadText: String get() = String(payload, Charsets.UTF_8)

    fun encode(checksum: Checksum = Checksum.DEFAULT): ByteArray {
        val bodyLen = payload.size + Protocol.CHECKSUM_LEN
        val out = ByteArray(Protocol.HEADER_LEN + payload.size + Protocol.CHECKSUM_LEN)
        // header
        Protocol.START_FLAG.copyInto(out, Protocol.Offset.START)
        putU32LE(out, Protocol.Offset.SEQ, seq)
        out[Protocol.Offset.VERSION] = version.toByte()
        out[Protocol.Offset.OPCODE] = opcode.toByte()
        putU16LE(out, Protocol.Offset.FLAGS, flags)
        putU16LE(out, Protocol.Offset.LENGTH, bodyLen)
        // payload
        payload.copyInto(out, Protocol.HEADER_LEN)
        // checksum peste tot cadrul, mai puțin ultimul octet
        out[out.size - 1] = checksum.compute(out, 0, out.size - 1)
        return out
    }

    companion object {
        /**
         * Construiește un cadru dintr-un payload JSON. `opcode` este tipul mesajului
         * din header (implicit REQUEST); codul operației (`opt`) stă în interiorul
         * payload-ului, nu în header.
         */
        fun ofJson(payload: Map<String, Any?>, seq: Int = 0, opcode: Int = Protocol.Op.REQUEST): Frame =
            Frame(opcode, Json.encode(payload).toByteArray(Charsets.UTF_8), seq)

        /** Decodează un cadru complet (deja reasamblat). Întoarce null dacă nu e valid. */
        fun decode(data: ByteArray, verifyChecksum: Boolean = false, checksum: Checksum = Checksum.DEFAULT): Frame? {
            if (data.size < Protocol.HEADER_LEN + Protocol.CHECKSUM_LEN) return null
            for (i in Protocol.START_FLAG.indices) if (data[i] != Protocol.START_FLAG[i]) return null
            val version = data[Protocol.Offset.VERSION].toInt() and 0xFF
            val opcode = data[Protocol.Offset.OPCODE].toInt() and 0xFF
            val seq = getU32LE(data, Protocol.Offset.SEQ)
            val flags = getU16LE(data, Protocol.Offset.FLAGS)
            val bodyLen = getU16LE(data, Protocol.Offset.LENGTH)
            val payloadLen = bodyLen - Protocol.CHECKSUM_LEN
            if (payloadLen < 0 || Protocol.HEADER_LEN + bodyLen > data.size) return null
            val payload = data.copyOfRange(Protocol.HEADER_LEN, Protocol.HEADER_LEN + payloadLen)
            if (verifyChecksum) {
                val expect = checksum.compute(data, 0, Protocol.HEADER_LEN + payloadLen)
                if (expect != data[Protocol.HEADER_LEN + payloadLen]) return null
            }
            return Frame(opcode, payload, seq, version, flags)
        }

        private fun putU16LE(b: ByteArray, off: Int, v: Int) {
            b[off] = (v and 0xFF).toByte(); b[off + 1] = ((v ushr 8) and 0xFF).toByte()
        }
        private fun putU32LE(b: ByteArray, off: Int, v: Int) {
            b[off] = (v and 0xFF).toByte(); b[off + 1] = ((v ushr 8) and 0xFF).toByte()
            b[off + 2] = ((v ushr 16) and 0xFF).toByte(); b[off + 3] = ((v ushr 24) and 0xFF).toByte()
        }
        private fun getU16LE(b: ByteArray, off: Int): Int =
            (b[off].toInt() and 0xFF) or ((b[off + 1].toInt() and 0xFF) shl 8)
        private fun getU32LE(b: ByteArray, off: Int): Int =
            (b[off].toInt() and 0xFF) or ((b[off + 1].toInt() and 0xFF) shl 8) or
            ((b[off + 2].toInt() and 0xFF) shl 16) or ((b[off + 3].toInt() and 0xFF) shl 24)
    }
}

/**
 * Checksum pluggable. Exemplul din documentație e SINTETIC și nu corespunde
 * niciunei scheme simple — algoritmul real se fixează aici după o captură pe
 * hardware (vezi docs/VALIDARE_PROTOCOL.md). Schimbi doar `DEFAULT`.
 */
fun interface Checksum {
    fun compute(data: ByteArray, from: Int, toExclusive: Int): Byte
    companion object {
        val SUM8 = Checksum { d, f, t -> var s = 0; for (i in f until t) s += d[i].toInt() and 0xFF; (s and 0xFF).toByte() }
        val XOR8 = Checksum { d, f, t -> var x = 0; for (i in f until t) x = x xor (d[i].toInt() and 0xFF); (x and 0xFF).toByte() }
        val SUM8_FROM_PAYLOAD = Checksum { d, _, t -> var s = 0; for (i in Protocol.HEADER_LEN until t) s += d[i].toInt() and 0xFF; (s and 0xFF).toByte() }
        /** Placeholder până la confirmarea pe hardware. */
        var DEFAULT: Checksum = SUM8
    }
}

